#[test]
fn exact_rules_cc_helper_internal_freezes_complete_recursive_producer() {
    assert_eq!(RULES_CC_HELPER_INTERNAL_SOURCE.lines().count(), 383);
    let hash = format!(
        "{:x}",
        Sha256::digest(RULES_CC_HELPER_INTERNAL_SOURCE.as_bytes())
    );
    assert_eq!(
        hash,
        "793ab429f8e397df9c486f4c3c7b5c57fae81c8432ba6d08189d65d75676dae1"
    );
    let child_owner = |label: &str, path: &str| BzlModuleIdentity {
        label: CanonicalLabel::parse(label).unwrap(),
        workspace_path: PathBuf::from(path),
        repository_mapping: Arc::from([]),
    };
    let skylib_owner = child_owner(
        "@@bazel_skylib+//lib:paths.bzl",
        "/bazel_skylib/lib/paths.bzl",
    );
    let internal_owner = child_owner(
        "@@rules_cc+//cc/private:cc_internal.bzl",
        "/rules_cc/cc/private/cc_internal.bzl",
    );
    let private_paths_owner = child_owner(
        "@@rules_cc+//cc/private:paths.bzl",
        "/rules_cc/cc/private/paths.bzl",
    );
    let skylib = eval_bzl_with_identity(PATHS_SOURCE, skylib_owner.clone()).unwrap();
    let internal =
        eval_bzl_with_identity(RULES_CC_INTERNAL_SOURCE, internal_owner.clone()).unwrap();
    let private_paths =
        eval_bzl_with_identity(RULES_CC_PRIVATE_PATHS_SOURCE, private_paths_owner.clone()).unwrap();
    let internal_load = "//cc/private:cc_internal.bzl";
    let private_paths_load = "//cc/private:paths.bzl";
    let helper = eval_bzl_with_loaded_children(
        RULES_CC_HELPER_INTERNAL_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/common:cc_helper_internal.bzl").unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/common/cc_helper_internal.bzl"),
            repository_mapping: Arc::from([(
                ApparentRepoName::new("bazel_skylib").unwrap(),
                CanonicalRepoName::new("bazel_skylib+").unwrap(),
            )]),
        },
        &[
            ("@bazel_skylib//lib:paths.bzl", skylib_owner, skylib.dupe()),
            (internal_load, internal_owner, internal.dupe()),
            (
                private_paths_load,
                private_paths_owner,
                private_paths.dupe(),
            ),
        ],
    )
    .unwrap();
    let public = |name| helper.get(name).unwrap();
    let private = |name| helper.get_any_visibility(name).unwrap().0;
    let skylib_paths = skylib.get("paths").unwrap();
    let absolute = private_paths.get("is_path_absolute").unwrap();
    let cc_internal = internal.get("cc_internal").unwrap();
    assert!(public("paths").value().ptr_eq(skylib_paths.value()));
    assert!(public("is_path_absolute").value().ptr_eq(absolute.value()));
    assert!(private("_cc_internal").value().ptr_eq(cc_internal.value()));
    for (name, kind) in [
        ("extensions", "struct"),
        ("artifact_category_names", "struct"),
        ("output_subdirectories", "struct"),
        ("check_private_api", "function"),
        ("wrap_with_check_private_api", "function"),
        ("root_relative_path", "function"),
    ] {
        assert_eq!(public(name).value().get_type(), kind);
    }
    assert_eq!(
        public("CREATE_COMPILE_ACTION_API_ALLOWLISTED_PACKAGES")
            .value()
            .get_type(),
        "list"
    );
    let provider = private("_ArtifactCategoryInfo");
    let raw = private("_unused_new_aci");
    assert_eq!(provider.value().get_type(), "provider_callable");
    assert_eq!(raw.value().get_type(), "function");
    let categories = private("_artifact_categories");
    let categories = FrozenListRef::from_value(categories.value()).unwrap();
    assert_eq!(categories.len(), 22);
    assert_eq!(categories[0].to_value().get_type(), "provider");
    let provider_id = loading_provider_id(categories[0].to_value());
    for category in categories.iter() {
        assert_eq!(loading_provider_id(category.to_value()), provider_id);
    }
    assert!(helper.get("_ArtifactCategoryInfo").is_err());
}

#[test]
fn exact_rules_cc_extra_link_library_freezes_complete_recursive_producer() {
    assert_eq!(RULES_CC_EXTRA_LINK_LIBRARY_SOURCE.lines().count(), 192);
    let hash = format!(
        "{:x}",
        Sha256::digest(RULES_CC_EXTRA_LINK_LIBRARY_SOURCE.as_bytes())
    );
    assert_eq!(
        hash,
        "522312ac48567566725f0768a6961fcaa78577fa24ac8007d5b1b8ca19698e82"
    );
    let owner = |label: &str, path: &str| BzlModuleIdentity {
        label: CanonicalLabel::parse(label).unwrap(),
        workspace_path: PathBuf::from(path),
        repository_mapping: Arc::from([]),
    };
    let skylib_owner = owner(
        "@@bazel_skylib+//lib:paths.bzl",
        "/bazel_skylib/lib/paths.bzl",
    );
    let internal_owner = owner(
        "@@rules_cc+//cc/private:cc_internal.bzl",
        "/rules_cc/cc/private/cc_internal.bzl",
    );
    let private_paths_owner = owner(
        "@@rules_cc+//cc/private:paths.bzl",
        "/rules_cc/cc/private/paths.bzl",
    );
    let helper_owner = owner(
        "@@rules_cc+//cc/common:cc_helper_internal.bzl",
        "/rules_cc/cc/common/cc_helper_internal.bzl",
    );
    let skylib = eval_bzl_with_identity(PATHS_SOURCE, skylib_owner.clone()).unwrap();
    let internal =
        eval_bzl_with_identity(RULES_CC_INTERNAL_SOURCE, internal_owner.clone()).unwrap();
    let private_paths =
        eval_bzl_with_identity(RULES_CC_PRIVATE_PATHS_SOURCE, private_paths_owner.clone()).unwrap();
    let internal_load = "//cc/private:cc_internal.bzl";
    let helper_load = "//cc/common:cc_helper_internal.bzl";
    let helper = eval_bzl_with_loaded_children(
        RULES_CC_HELPER_INTERNAL_SOURCE,
        BzlModuleIdentity {
            repository_mapping: Arc::from([(
                ApparentRepoName::new("bazel_skylib").unwrap(),
                CanonicalRepoName::new("bazel_skylib+").unwrap(),
            )]),
            ..helper_owner.clone()
        },
        &[
            ("@bazel_skylib//lib:paths.bzl", skylib_owner, skylib),
            (internal_load, internal_owner.clone(), internal.dupe()),
            ("//cc/private:paths.bzl", private_paths_owner, private_paths),
        ],
    )
    .unwrap();
    let extra = eval_bzl_with_loaded_children(
        RULES_CC_EXTRA_LINK_LIBRARY_SOURCE,
        owner(
            "@@rules_cc+//cc/private/link:create_extra_link_time_library.bzl",
            "/rules_cc/cc/private/link/create_extra_link_time_library.bzl",
        ),
        &[
            (helper_load, helper_owner, helper.dupe()),
            (internal_load, internal_owner, internal.dupe()),
        ],
    )
    .unwrap();
    let public = |name| extra.get(name).unwrap();
    let private = |name| extra.get_any_visibility(name).unwrap().0;
    assert!(
        public("check_private_api")
            .value()
            .ptr_eq(helper.get("check_private_api").unwrap().value())
    );
    assert!(
        private("_cc_internal")
            .value()
            .ptr_eq(internal.get("cc_internal").unwrap().value())
    );
    let providers = [
        public("ExtraLinkTimeLibraryInfo"),
        public("ExtraLibraryInfo"),
        private("_KeyInfo"),
        public("ExtraLinkTimeLibrariesInfo"),
    ];
    for provider in &providers {
        assert_eq!(provider.value().get_type(), "provider_callable");
    }
    for (index, left) in providers.iter().enumerate() {
        for right in &providers[index + 1..] {
            assert!(!left.value().ptr_eq(right.value()));
        }
    }
    assert!(extra.get("_KeyInfo").is_err());
    let empty = private("_EMPTY");
    assert_eq!(empty.value().get_type(), "provider");
    let empty_id = loading_provider_id(empty.value()).unwrap();
    assert_eq!(
        empty_id.source_label(),
        "@@rules_cc+//cc/private/link:create_extra_link_time_library.bzl"
    );
    assert_eq!(empty_id.exported_name(), "ExtraLinkTimeLibrariesInfo");
    let scratch = Module::new();
    let libraries = empty
        .value()
        .to_value()
        .get_attr("libraries", scratch.heap())
        .unwrap()
        .unwrap();
    assert_eq!(FrozenListRef::from_value(libraries).unwrap().len(), 0);
    for name in [
        "create_extra_link_time_library",
        "create_extra_link_time_libraries",
        "merge_extra_link_time_libraries",
        "build_libraries",
    ] {
        assert_eq!(public(name).value().get_type(), "function");
    }
    assert_eq!(private("_merge_values").value().get_type(), "function");
    assert!(extra.get("_merge_values").is_err());
}

fn complete_rules_cc_cc_info_children() -> Vec<(&'static str, BzlModuleIdentity, FrozenModule)> {
    let owner = |label: &str, path: &str| BzlModuleIdentity {
        label: CanonicalLabel::parse(label).unwrap(),
        workspace_path: PathBuf::from(path),
        repository_mapping: Arc::from([]),
    };
    let [
        skylib_owner,
        internal_owner,
        private_paths_owner,
        helper_owner,
        extra_owner,
    ] = [
        (
            "@@bazel_skylib+//lib:paths.bzl",
            "/bazel_skylib/lib/paths.bzl",
        ),
        (
            "@@rules_cc+//cc/private:cc_internal.bzl",
            "/rules_cc/cc/private/cc_internal.bzl",
        ),
        (
            "@@rules_cc+//cc/private:paths.bzl",
            "/rules_cc/cc/private/paths.bzl",
        ),
        (
            "@@rules_cc+//cc/common:cc_helper_internal.bzl",
            "/rules_cc/cc/common/cc_helper_internal.bzl",
        ),
        (
            "@@rules_cc+//cc/private/link:create_extra_link_time_library.bzl",
            "/rules_cc/cc/private/link/create_extra_link_time_library.bzl",
        ),
    ]
    .map(|(label, path)| owner(label, path));
    let helper_owner = BzlModuleIdentity {
        repository_mapping: Arc::from([(
            ApparentRepoName::new("bazel_skylib").unwrap(),
            CanonicalRepoName::new("bazel_skylib+").unwrap(),
        )]),
        ..helper_owner
    };
    let skylib = eval_bzl_with_identity(PATHS_SOURCE, skylib_owner.clone()).unwrap();
    let internal =
        eval_bzl_with_identity(RULES_CC_INTERNAL_SOURCE, internal_owner.clone()).unwrap();
    let private_paths =
        eval_bzl_with_identity(RULES_CC_PRIVATE_PATHS_SOURCE, private_paths_owner.clone()).unwrap();
    let helper = eval_bzl_with_loaded_children(
        RULES_CC_HELPER_INTERNAL_SOURCE,
        helper_owner.clone(),
        &[
            (
                "@bazel_skylib//lib:paths.bzl",
                skylib_owner.clone(),
                skylib.dupe(),
            ),
            (
                "//cc/private:cc_internal.bzl",
                internal_owner.clone(),
                internal.dupe(),
            ),
            ("//cc/private:paths.bzl", private_paths_owner, private_paths),
        ],
    )
    .unwrap();
    let extra = eval_bzl_with_loaded_children(
        RULES_CC_EXTRA_LINK_LIBRARY_SOURCE,
        extra_owner.clone(),
        &[
            (
                "//cc/common:cc_helper_internal.bzl",
                helper_owner.clone(),
                helper.dupe(),
            ),
            (
                "//cc/private:cc_internal.bzl",
                internal_owner.clone(),
                internal.dupe(),
            ),
        ],
    )
    .unwrap();
    vec![
        ("@bazel_skylib//lib:paths.bzl", skylib_owner, skylib),
        ("//cc/common:cc_helper_internal.bzl", helper_owner, helper),
        ("//cc/private:cc_internal.bzl", internal_owner, internal),
        (
            "//cc/private/link:create_extra_link_time_library.bzl",
            extra_owner,
            extra,
        ),
    ]
}

fn assert_cc_info_interface_bindings(
    cc_info: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let public = |name| cc_info.get(name).unwrap();
    let private = |name| cc_info.get_any_visibility(name).unwrap().0;
    assert!(
        public("paths")
            .value()
            .ptr_eq(children[0].2.get("paths").unwrap().value())
    );
    assert!(
        public("check_private_api")
            .value()
            .ptr_eq(children[1].2.get("check_private_api").unwrap().value())
    );
    assert!(
        private("_cc_internal")
            .value()
            .ptr_eq(children[2].2.get("cc_internal").unwrap().value())
    );
    for name in [
        "create_extra_link_time_libraries",
        "merge_extra_link_time_libraries",
    ] {
        assert!(
            public(name)
                .value()
                .ptr_eq(children[3].2.get(name).unwrap().value())
        );
    }
    for (value, name) in [
        (
            public("CcCompilationContextInfo"),
            "CcCompilationContextInfo",
        ),
        (public("CcLinkingContextInfo"), "CcLinkingContextInfo"),
        (public("CcNativeLibraryInfo"), "CcNativeLibraryInfo"),
        (public("CcDebugContextInfo"), "CcDebugContextInfo"),
        (private("_ModuleMapInfo"), "_ModuleMapInfo"),
    ] {
        let provider = FrozenUserProviderCallable::from_value(value.value()).unwrap();
        assert_eq!(
            provider.id().source_label(),
            "@@rules_cc+//cc/private:cc_info.bzl"
        );
        assert_eq!(provider.id().exported_name(), name);
    }
    let providers = [
        public("CcCompilationContextInfo"),
        public("CcLinkingContextInfo"),
        public("CcNativeLibraryInfo"),
        public("CcDebugContextInfo"),
        private("_ModuleMapInfo"),
        public("CcInfo"),
    ];
    for (index, left) in providers.iter().enumerate() {
        assert_eq!(left.value().get_type(), "provider_callable");
        for right in &providers[index + 1..] {
            assert!(!left.value().ptr_eq(right.value()));
        }
    }
    assert!(cc_info.get("_ModuleMapInfo").is_err());
    let cc = public("CcInfo");
    assert_eq!(
        cc.value().to_string(),
        "provider[@@rules_cc+//cc/private:cc_info.bzl%CcInfo]"
    );
    assert_eq!(private("_").value().get_type(), "function");
    assert!(cc_info.get("_").is_err());
    for name in "create_module_map create_separate_module_map create_linking_context merge_linking_contexts create_debug_context merge_debug_context create_compilation_context create_compilation_context_with_extra_header_tokens create_cc_compilation_context_with_cpp20_modules merge_cc_infos".split_whitespace() {
        assert_eq!(public(name).value().get_type(), "function");
    }
    for name in "_create_cc_info _normalize_paths _flat_depset _merge_compilation_contexts"
        .split_whitespace()
    {
        assert_eq!(private(name).value().get_type(), "function");
        assert!(cc_info.get(name).is_err());
    }
}

#[rustfmt::skip]
fn assert_cc_info_empty_context_shapes(cc_info: &FrozenModule) {
    let public = |name| cc_info.get(name).unwrap();
    let private = |name| cc_info.get_any_visibility(name).unwrap().0;
    let compilation = public("EMPTY_COMPILATION_CONTEXT");
    let linking = private("_EMPTY_LINKING_CONTEXT");
    let debug = private("_EMPTY_DEBUG_CONTEXT");
    for (context, name) in [(&compilation, "CcCompilationContextInfo"), (&linking, "CcLinkingContextInfo"), (&debug, "CcDebugContextInfo")] {
        let id = loading_provider_id(context.value()).unwrap();
        assert_eq!((id.source_label(), id.exported_name()), ("@@rules_cc+//cc/private:cc_info.bzl", name));
    }
    let scratch = Module::new();
    macro_rules! field {
        ($value:expr, $name:expr) => {
            $value.value().to_value().get_attr($name, scratch.heap()).unwrap().unwrap()
        };
    }
    for (context, lists, depsets, none) in [
        (&compilation, "direct_headers direct_public_headers direct_private_headers direct_textual_headers", "defines local_defines headers includes quote_includes system_includes framework_includes external_includes validation_artifacts _virtual_to_original_headers _exporting_module_maps _exporting_module_map_files _non_code_inputs _transitive_modules _transitive_pic_modules _direct_module_maps _modules_info_files _pic_modules_info_files _module_files _pic_module_files", "_module_map"),
        (&linking, "", "linker_inputs", "_extra_link_time_libraries"), (&debug, "", "files pic_files", ""),
    ] {
        for name in lists.split_whitespace() { assert_eq!(FrozenListRef::from_value(field!(context, name)).unwrap().len(), 0); }
        for name in depsets.split_whitespace() { assert_eq!(StarlarkDepset::direct_from_value(field!(context, name)).unwrap().len(), 0); }
        for name in none.split_whitespace() { assert_eq!(field!(context, name).get_type(), "NoneType"); }
    }
    let header = field!(&compilation, "_header_info");
    assert_eq!(header.get_type(), "HeaderInfo");
    for name in "modular_public_headers modular_private_headers textual_headers separate_module_headers".split_whitespace() {
        assert_eq!(FrozenListRef::from_value(header.get_attr(name, scratch.heap()).unwrap().unwrap()).unwrap().len(), 0);
    }
    for name in "header_module pic_header_module separate_module separate_pic_module".split_whitespace() {
        assert_eq!(header.get_attr(name, scratch.heap()).unwrap().unwrap().get_type(), "NoneType");
    }
    assert!(cc_info.get("_EMPTY_LINKING_CONTEXT").is_err());
    assert!(cc_info.get("_EMPTY_DEBUG_CONTEXT").is_err());
}
