fn assert_compilation_outputs_interfaces(
    outputs: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let public = |name| outputs.get(name).unwrap();
    let private = |name| outputs.get_any_visibility(name).unwrap().0;
    assert!(
        public("wrap_with_check_private_api").value().ptr_eq(
            children[0]
                .2
                .get("wrap_with_check_private_api")
                .unwrap()
                .value()
        )
    );
    assert!(
        private("_PRIVATE_STARLARKIFICATION_ALLOWLIST")
            .value()
            .ptr_eq(
                children[0]
                    .2
                    .get("PRIVATE_STARLARKIFICATION_ALLOWLIST")
                    .unwrap()
                    .value()
            )
    );
    assert!(
        private("_cc_internal")
            .value()
            .ptr_eq(children[1].2.get("cc_internal").unwrap().value())
    );
    for name in [
        "EMPTY_LTO_COMPILATION_CONTEXT",
        "merge_lto_compilation_contexts",
    ] {
        assert!(
            public(name)
                .value()
                .ptr_eq(children[2].2.get(name).unwrap().value())
        );
    }
    for (value, name) in [
        (
            private("_UnboundValueProviderDoNotUse"),
            "_UnboundValueProviderDoNotUse",
        ),
        (
            public("CcCompilationOutputsInfo"),
            "CcCompilationOutputsInfo",
        ),
    ] {
        assert_eq!(value.value().get_type(), "provider_callable");
        let provider = FrozenUserProviderCallable::from_value(value.value()).unwrap();
        assert_eq!(
            provider.id().source_label(),
            "@@rules_cc+//cc/private/compile:cc_compilation_outputs.bzl"
        );
        assert_eq!(provider.id().exported_name(), name);
    }
    assert!(
        !private("_UnboundValueProviderDoNotUse")
            .value()
            .ptr_eq(public("CcCompilationOutputsInfo").value())
    );
    for name in [
        "_PRIVATE_STARLARKIFICATION_ALLOWLIST",
        "_cc_internal",
        "_UnboundValueProviderDoNotUse",
        "_UNBOUND",
    ] {
        assert!(outputs.get(name).is_err());
    }
    let unbound = private("_UNBOUND");
    assert_eq!(unbound.value().get_type(), "provider");
    let id = loading_provider_id(unbound.value()).unwrap();
    assert_eq!(
        id.source_label(),
        "@@rules_cc+//cc/private/compile:cc_compilation_outputs.bzl"
    );
    assert_eq!(id.exported_name(), "_UnboundValueProviderDoNotUse");
    for (name, is_private) in [
        ("create_compilation_outputs_internal", false),
        ("_validate_extensions", true),
        ("_to_list", true),
        ("create_compilation_outputs", false),
        ("merge_compilation_outputs", false),
    ] {
        let value = if is_private {
            private(name)
        } else {
            public(name)
        };
        assert_eq!(value.value().get_type(), "function");
        if is_private {
            assert!(outputs.get(name).is_err());
        }
    }
}
