fn assert_compilation_helper_interfaces(
    helper: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let public = |name| helper.get(name).unwrap();
    let private = |name| helper.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        ("paths", 0, "paths"),
        ("get_relative_path", 1, "get_relative_path"),
        ("package_source_root", 1, "package_source_root"),
        ("repository_exec_path", 1, "repository_exec_path"),
        (
            "STRIP_INCLUDE_PREFIX_APPLIES_TO_TEXTUAL_HEADERS",
            2,
            "STRIP_INCLUDE_PREFIX_APPLIES_TO_TEXTUAL_HEADERS",
        ),
        (
            "USE_EXEC_ROOT_FOR_VIRTUAL_INCLUDES_SYMLINKS",
            2,
            "USE_EXEC_ROOT_FOR_VIRTUAL_INCLUDES_SYMLINKS",
        ),
        (
            "create_compilation_context",
            3,
            "create_compilation_context",
        ),
        ("create_module_map", 3, "create_module_map"),
    ] {
        assert!(
            public(name)
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value()),
            "{name}"
        );
    }
    assert!(
        private("_cc_internal")
            .value()
            .ptr_eq(children[4].2.get("cc_internal").unwrap().value())
    );
    assert_eq!(
        private("_VIRTUAL_INCLUDES_DIR").unpack_str(),
        Some("_virtual_includes")
    );
    let module_map_info = private("_ModuleMapInfo");
    let provider = FrozenUserProviderCallable::from_value(module_map_info.value()).unwrap();
    assert_eq!(
        (provider.id().source_label(), provider.id().exported_name()),
        (
            "@@rules_cc+//cc/private/compile:cc_compilation_helper.bzl",
            "_ModuleMapInfo"
        )
    );
    assert!(helper.get("_ModuleMapInfo").is_err());
    let private_names = "_include_dir _repo_relative_path _enabled _compute_public_headers _generates_header_module _header_module_artifact _collect_module_maps _module_map_struct_to_module_map_content _create_module_map_action _init_cc_compilation_context";
    assert_eq!(private_names.split_whitespace().count(), 10);
    for name in private_names.split_whitespace() {
        assert_eq!(private(name).value().get_type(), "function", "{name}");
        assert!(helper.get(name).is_err(), "{name}");
    }
    for name in ["dotd_files_enabled", "serialized_diagnostics_file_enabled"] {
        assert_eq!(public(name).value().get_type(), "function", "{name}");
    }
    let mut names = helper.names().map(|name| name.as_str()).collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected = "STRIP_INCLUDE_PREFIX_APPLIES_TO_TEXTUAL_HEADERS USE_EXEC_ROOT_FOR_VIRTUAL_INCLUDES_SYMLINKS cc_compilation_helper create_compilation_context create_module_map dotd_files_enabled get_relative_path package_source_root paths repository_exec_path serialized_diagnostics_file_enabled".split_whitespace().collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut names_any = helper
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    names_any.sort_unstable();
    expected.extend(private_names.split_whitespace());
    expected.extend(["_ModuleMapInfo", "_VIRTUAL_INCLUDES_DIR", "_cc_internal"]);
    expected.sort_unstable();
    assert_eq!(names_any, expected);
    let helper_binding = public("cc_compilation_helper");
    let structure = StructRef::from_value(helper_binding.value()).unwrap();
    assert_eq!(structure.iter().count(), 1);
    let init = structure.iter().next().unwrap();
    assert_eq!(init.0.as_str(), "init_cc_compilation_context");
    assert!(
        init.1
            .ptr_eq(private("_init_cc_compilation_context").value())
    );
}

