fn complete_rules_cc_compile_build_variables_children()
-> Vec<(&'static str, BzlModuleIdentity, FrozenModule)> {
    let previous = complete_rules_cc_cc_info_children();
    let native_owner = BzlModuleIdentity {
        label: CanonicalLabel::parse("@@rules_cc+//cc/private/rules_impl:native_cc_common.bzl")
            .unwrap(),
        workspace_path: PathBuf::from("/rules_cc/cc/private/rules_impl/native_cc_common.bzl"),
        repository_mapping: Arc::from([]),
    };
    let native_globals = loading_globals();
    let predeclared_cc_common = native_globals
        .iter()
        .find_map(|(name, value)| (name == "cc_common").then_some(value))
        .unwrap();
    let native = eval_bzl_with_identity_and_globals(
        RULES_CC_NATIVE_CC_COMMON_SOURCE,
        native_owner.clone(),
        &native_globals,
    )
    .unwrap();
    assert!(
        native
            .get("native_cc_common")
            .unwrap()
            .value()
            .ptr_eq(predeclared_cc_common.to_value())
    );
    vec![
        (
            "//cc/common:cc_helper_internal.bzl",
            previous[1].1.clone(),
            previous[1].2.dupe(),
        ),
        (
            "//cc/private:cc_internal.bzl",
            previous[2].1.clone(),
            previous[2].2.dupe(),
        ),
        (
            "//cc/private/rules_impl:native_cc_common.bzl",
            native_owner,
            native,
        ),
    ]
}

fn assert_compile_build_variables_interfaces(
    variables: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let public = |name| variables.get(name).unwrap();
    let private = |name| variables.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        ("extensions", 0, "extensions"),
        (
            "_PRIVATE_STARLARKIFICATION_ALLOWLIST",
            0,
            "PRIVATE_STARLARKIFICATION_ALLOWLIST",
        ),
        ("_cc_internal", 1, "cc_internal"),
        ("_cc_common_internal", 2, "native_cc_common"),
    ] {
        let value = if name.starts_with('_') {
            private(name)
        } else {
            public(name)
        };
        assert!(
            value
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value()),
            "{name}"
        );
    }
    let vars = private("_VARS");
    let vars = StructRef::from_value(vars.value()).unwrap();
    let expected = "FRAMEWORK_PATHS|framework_include_paths SOURCE_FILE|source_file USER_COMPILE_FLAGS|user_compile_flags OUTPUT_FILE|output_file DEPENDENCY_FILE|dependency_file SERIALIZED_DIAGNOSTICS_FILE|serialized_diagnostics_file MODULE_NAME|module_name INCLUDE_PATHS|include_paths QUOTE_INCLUDE_PATHS|quote_include_paths SYSTEM_INCLUDE_PATHS|system_include_paths EXTERNAL_INCLUDE_PATHS|external_include_paths MODULE_MAP_FILE|module_map_file DEPENDENT_MODULE_MAP_FILES|dependent_module_map_files MODULE_FILES|module_files PREPROCESSOR_DEFINES|preprocessor_defines GCOV_GCNO_FILE|gcov_gcno_file LTO_INDEXING_BITCODE_FILE|lto_indexing_bitcode_file THINLTO_INDEX|thinlto_index THINLTO_INPUT_BITCODE_FILE|thinlto_input_bitcode_file THINLTO_OUTPUT_OBJECT_FILE|thinlto_output_object_file IS_USING_FISSION|is_using_fission PER_OBJECT_DEBUG_INFO_FILE|per_object_debug_info_file PIC|pic IS_USING_MEMPROF|is_using_memprof INCLUDES|includes";
    assert_eq!(expected.split_whitespace().count(), 25);
    assert_eq!(vars.iter().count(), 25);
    for row in expected.split_whitespace() {
        let (name, value) = row.split_once('|').unwrap();
        assert_eq!(
            vars.iter()
                .find_map(|(field, value)| (field.as_str() == name).then_some(value))
                .unwrap()
                .unpack_str(),
            Some(value)
        );
    }
    let provider_binding = private("_UnboundValueProviderDoNotUse");
    assert_eq!(provider_binding.value().get_type(), "provider_callable");
    let provider = FrozenUserProviderCallable::from_value(provider_binding.value()).unwrap();
    assert_eq!(
        (provider.id().source_label(), provider.id().exported_name()),
        (
            "@@rules_cc+//cc/private/compile:compile_build_variables.bzl",
            "_UnboundValueProviderDoNotUse"
        )
    );
    let unbound = private("_UNBOUND");
    assert_eq!(unbound.value().get_type(), "provider");
    let id = loading_provider_id(unbound.value()).unwrap();
    assert_eq!(
        (id.source_label(), id.exported_name()),
        (
            "@@rules_cc+//cc/private/compile:compile_build_variables.bzl",
            "_UnboundValueProviderDoNotUse"
        )
    );
    let set = private("_SOURCE_TYPES_FOR_CXXOPTS");
    assert_eq!(set.value().get_type(), "set");
    let scratch = Module::new();
    let actual = set
        .value()
        .to_value()
        .iterate(scratch.heap())
        .unwrap()
        .map(|value| value.unpack_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(actual, ".cc .cpp .cxx .c++ .C .cu .cl .h .hh .hpp .ipp .hxx .h++ .inc .inl .tlh .tli .H .tcc .ipb .cppmap .mm".split_whitespace().collect::<Vec<_>>());
    let private_functions = "_setup_common_compile_build_variables_internal _get_fdo_build_stamp _copts_from_options _setup_fdo_build_variables _get_auxiliary_fdo_inputs_list _should_pass_propeller_profiles _compute_all_linkstamp_defines";
    let public_functions = "create_compile_variables setup_common_compile_build_variables get_specific_compile_build_variables get_copts get_fdo_variables_and_inputs get_linkstamp_compile_variables";
    for name in private_functions.split_whitespace() {
        assert_eq!(private(name).value().get_type(), "function", "{name}");
        assert!(variables.get(name).is_err(), "{name}");
    }
    for name in public_functions.split_whitespace() {
        assert_eq!(public(name).value().get_type(), "function", "{name}");
    }
    let mut names = variables
        .names()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected = "extensions create_compile_variables setup_common_compile_build_variables get_specific_compile_build_variables get_copts get_fdo_variables_and_inputs get_linkstamp_compile_variables".split_whitespace().collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut all = variables
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    expected.extend(private_functions.split_whitespace());
    expected.extend("_PRIVATE_STARLARKIFICATION_ALLOWLIST _cc_internal _cc_common_internal _VARS _UnboundValueProviderDoNotUse _UNBOUND _SOURCE_TYPES_FOR_CXXOPTS".split_whitespace());
    expected.sort_unstable();
    assert_eq!(all, expected);
}

