#[test]
fn exact_rules_cc_create_library_to_link_freezes_complete_producer() {
    assert_eq!(RULES_CC_CREATE_LIBRARY_TO_LINK_SOURCE.lines().count(), 291);
    assert_eq!(
        format!(
            "{:x}",
            Sha256::digest(RULES_CC_CREATE_LIBRARY_TO_LINK_SOURCE.as_bytes())
        ),
        "5f57423312f24392f106aeb5959485c4f30c54ee2d8e926a45934de51a2455d1"
    );
    let children = complete_rules_cc_create_library_to_link_children();
    for (child, label) in children.iter().zip([
        "@@bazel_skylib+//lib:paths.bzl",
        "@@rules_cc+//cc/common:cc_helper_internal.bzl",
        "@@rules_cc+//cc/private:cc_internal.bzl",
        "@@rules_cc+//cc/private/compile:lto_compilation_context.bzl",
        "@@rules_cc+//cc/private/link:lto_backends.bzl",
    ]) {
        assert_eq!(child.1.label, CanonicalLabel::parse(label).unwrap());
    }
    let skylib_mapping = Arc::from([(
        ApparentRepoName::new("bazel_skylib").unwrap(),
        CanonicalRepoName::new("bazel_skylib+").unwrap(),
    )]);
    assert!(children[0].1.repository_mapping.is_empty());
    assert_eq!(children[1].1.repository_mapping, skylib_mapping);
    assert!(children[2].1.repository_mapping.is_empty());
    assert!(children[3].1.repository_mapping.is_empty());
    assert_eq!(children[4].1.repository_mapping, skylib_mapping);
    let module = eval_bzl_with_loaded_children(
        RULES_CC_CREATE_LIBRARY_TO_LINK_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/private/link:create_library_to_link.bzl")
                .unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/private/link/create_library_to_link.bzl"),
            repository_mapping: Arc::from([(
                ApparentRepoName::new("bazel_skylib").unwrap(),
                CanonicalRepoName::new("bazel_skylib+").unwrap(),
            )]),
        },
        &children,
    )
    .unwrap();
    let public = |name| module.get(name).unwrap();
    let private = |name| module.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        ("paths", 0, "paths"),
        (
            "is_versioned_shared_library",
            1,
            "is_versioned_shared_library",
        ),
        (
            "path_contains_up_level_references",
            1,
            "path_contains_up_level_references",
        ),
        ("_cc_internal", 2, "cc_internal"),
        ("_EMPTY_LTO", 3, "EMPTY_LTO_COMPILATION_CONTEXT"),
        (
            "create_shared_non_lto_artifacts",
            4,
            "create_shared_non_lto_artifacts",
        ),
    ] {
        let value = if name.starts_with('_') {
            private(name)
        } else {
            public(name)
        };
        assert!(
            value
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value())
        );
    }
    assert_eq!(
        private("_warning").value().unpack_str(),
        Some(
            " Don't use this field. It's intended for internal use and will be changed or removed\n    without warning."
        )
    );
    let provider_binding = public("LibraryToLinkInfo");
    let provider = FrozenUserProviderCallable::from_value(provider_binding.value()).unwrap();
    assert_eq!(
        (provider.id().source_label(), provider.id().exported_name()),
        (
            "@@rules_cc+//cc/private/link:create_library_to_link.bzl",
            "LibraryToLinkInfo"
        )
    );
    for name in "make_library_to_link create_library_to_link".split_whitespace() {
        assert_eq!(public(name).value().get_type(), "function");
    }
    for name in "_validate_symlink_path _validate_extension".split_whitespace() {
        assert_eq!(private(name).value().get_type(), "function");
        assert!(module.get(name).is_err());
    }
    let mut names = module.names().map(|name| name.as_str()).collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected = "paths is_versioned_shared_library path_contains_up_level_references create_shared_non_lto_artifacts LibraryToLinkInfo make_library_to_link create_library_to_link".split_whitespace().collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    expected.extend(
        "_cc_internal _EMPTY_LTO _warning _validate_symlink_path _validate_extension"
            .split_whitespace(),
    );
    expected.sort_unstable();
    assert_eq!(all, expected);
}

