fn assert_rules_cc_link_build_variables_interfaces(
    module: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule); 2],
) {
    let public = |name| module.get(name).unwrap();
    let private = |name| module.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        ("get_relative_path", 0, "get_relative_path"),
        (
            "should_create_per_object_debug_info",
            0,
            "should_create_per_object_debug_info",
        ),
        ("artifact_category", 0, "artifact_category_names"),
        ("_cc_internal", 1, "cc_internal"),
    ] {
        let binding = if name.starts_with('_') {
            private(name)
        } else {
            public(name)
        };
        assert!(
            binding
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value()),
            "{name}"
        );
    }
    assert!(module.get("_cc_internal").is_err());
    let variables_binding = public("LINK_BUILD_VARIABLES");
    let variables = StructRef::from_value(variables_binding.value()).unwrap();
    let expected = "OUTPUT_EXECPATH|output_execpath LIBRARIES_TO_LINK|libraries_to_link RUNTIME_LIBRARY_SEARCH_DIRECTORIES|runtime_library_search_directories LIBRARY_SEARCH_DIRECTORIES|library_search_directories RUNTIME_SOLIB_NAME|runtime_solib_name GENERATE_INTERFACE_LIBRARY|generate_interface_library INTERFACE_LIBRARY_BUILDER|interface_library_builder_path INTERFACE_LIBRARY_INPUT|interface_library_input_path INTERFACE_LIBRARY_OUTPUT|interface_library_output_path USER_LINK_FLAGS|user_link_flags FORCE_PIC|force_pic STRIP_DEBUG_SYMBOLS|strip_debug_symbols IS_CC_TEST|is_cc_test IS_USING_FISSION|is_using_fission LINKER_PARAM_FILE|linker_param_file THINLTO_PARAM_FILE|thinlto_param_file THINLTO_OPTIONAL_PARAMS_FILE|thinlto_optional_params_file THINLTO_INDEXING_PARAM_FILE|thinlto_indexing_param_file THINLTO_PREFIX_REPLACE|thinlto_prefix_replace THINLTO_OBJECT_SUFFIX_REPLACE|thinlto_object_suffix_replace THINLTO_MERGED_OBJECT_FILE|thinlto_merged_object_file FDO_INSTRUMENT_PATH|fdo_instrument_path CS_FDO_INSTRUMENT_PATH|cs_fdo_instrument_path PROPELLER_OPTIMIZE_LD_PATH|propeller_optimize_ld_path";
    assert_eq!(variables.iter().count(), 24);
    for row in expected.split_whitespace() {
        let (name, value) = row.split_once('|').unwrap();
        assert_eq!(
            variables
                .iter()
                .find_map(|(field, actual)| (field.as_str() == name).then_some(actual))
                .unwrap()
                .unpack_str(),
            Some(value)
        );
    }
    let dont_binding = private("_DONT_GENERATE_INTERFACE_LIBRARY");
    assert!(module.get("_DONT_GENERATE_INTERFACE_LIBRARY").is_err());
    let mut dont = DictRef::from_value(dont_binding.value())
        .unwrap()
        .iter()
        .map(|(key, value)| (key.unpack_str().unwrap(), value.unpack_str().unwrap()))
        .collect::<Vec<_>>();
    dont.sort_unstable();
    assert_eq!(
        dont,
        [
            ("generate_interface_library", "no"),
            ("interface_library_builder_path", "ignored"),
            ("interface_library_input_path", "ignored"),
            ("interface_library_output_path", "ignored"),
        ]
    );
    let public_functions = "create_link_variables setup_common_linking_variables setup_linking_variables setup_lto_indexing_variables";
    for name in public_functions.split_whitespace() {
        assert_eq!(public(name).value().get_type(), "function", "{name}");
    }
    assert_eq!(private("_remove_pie").value().get_type(), "function");
    assert!(module.get("_remove_pie").is_err());
    let mut names = module.names().map(|name| name.as_str()).collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected = "get_relative_path should_create_per_object_debug_info artifact_category LINK_BUILD_VARIABLES create_link_variables setup_common_linking_variables setup_linking_variables setup_lto_indexing_variables".split_whitespace().collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    expected.extend([
        "_cc_internal",
        "_remove_pie",
        "_DONT_GENERATE_INTERFACE_LIBRARY",
    ]);
    expected.sort_unstable();
    assert_eq!(all, expected);
}

