fn assert_rules_cc_link_interfaces(
    module: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let public = |name| module.get(name).unwrap();
    let private = |name| module.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        ("_cc_internal", 0, "cc_internal"),
        ("EMPTY_COMPILATION_OUTPUTS", 1, "EMPTY_COMPILATION_OUTPUTS"),
        ("create_cc_link_actions", 2, "create_cc_link_actions"),
        ("LINKING_MODE", 3, "LINKING_MODE"),
        ("LINK_TARGET_TYPE", 3, "LINK_TARGET_TYPE"),
    ] {
        let binding = if name.starts_with('_') {
            private(name)
        } else {
            public(name)
        };
        assert!(
            binding
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value()),
            "{name}"
        );
    }
    assert!(module.get("_cc_internal").is_err());
    let table_binding = private("_TARGET_TYPE");
    assert!(module.get("_TARGET_TYPE").is_err());
    let table = DictRef::from_value(table_binding.value()).unwrap();
    assert_eq!(table.len(), 5);
    let target_binding = children[3].2.get("LINK_TARGET_TYPE").unwrap();
    let targets = StructRef::from_value(target_binding.value()).unwrap();
    let target = |name: &str| {
        targets
            .iter()
            .find_map(|(field, value)| (field.as_str() == name).then_some(value))
            .unwrap()
    };
    for (language, output, static_type, dynamic_type) in [
        ("cpp", "executable", None, Some("EXECUTABLE")),
        ("cpp", "dynamic_library", None, Some("DYNAMIC_LIBRARY")),
        ("objc", "executable", None, Some("OBJC_EXECUTABLE")),
        ("objcpp", "executable", None, Some("OBJC_EXECUTABLE")),
        ("objc", "archive", Some("OBJC_FULLY_LINKED_ARCHIVE"), None),
    ] {
        let value = table
            .iter()
            .find_map(|(key, value)| {
                let key = TupleRef::from_value(key)?;
                let mut parts = key.iter();
                (key.len() == 2
                    && parts.next().unwrap().unpack_str() == Some(language)
                    && parts.next().unwrap().unpack_str() == Some(output))
                .then_some(value)
            })
            .unwrap();
        let pair = TupleRef::from_value(value).unwrap();
        assert_eq!(pair.len(), 2);
        for (actual, expected) in pair.iter().zip([static_type, dynamic_type]) {
            if let Some(name) = expected {
                assert!(actual.ptr_eq(target(name)), "{language}/{output}/{name}");
            } else {
                assert!(actual.is_none(), "{language}/{output}");
            }
        }
    }
    assert_eq!(public("link").value().get_type(), "function");
    let mut names = module.names().map(|name| name.as_str()).collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected =
        "EMPTY_COMPILATION_OUTPUTS create_cc_link_actions LINKING_MODE LINK_TARGET_TYPE link"
            .split_whitespace()
            .collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    expected.extend(["_TARGET_TYPE", "_cc_internal"]);
    expected.sort_unstable();
    assert_eq!(all, expected);
}

#[test]
fn exact_rules_cc_link_freezes_complete_producer() {
    assert_eq!(RULES_CC_LINK_SOURCE.lines().count(), 197);
    assert_eq!(
        format!("{:x}", Sha256::digest(RULES_CC_LINK_SOURCE.as_bytes())),
        "666e819dee4777d0c3d8624e18588a905046532a6668d89d5744419cbee4a0e2"
    );
    let children = complete_rules_cc_link_children();
    for (child, label) in children.iter().zip([
        "@@rules_cc+//cc/private:cc_internal.bzl",
        "@@rules_cc+//cc/private/compile:cc_compilation_outputs.bzl",
        "@@rules_cc+//cc/private/link:cc_linking_helper.bzl",
        "@@rules_cc+//cc/private/link:target_types.bzl",
    ]) {
        assert_eq!(child.1.label, CanonicalLabel::parse(label).unwrap());
    }
    for child in [&children[0], &children[1], &children[3]] {
        assert!(child.1.repository_mapping.is_empty());
    }
    assert_eq!(
        children[2].1.repository_mapping,
        Arc::from([(
            ApparentRepoName::new("bazel_skylib").unwrap(),
            CanonicalRepoName::new("bazel_skylib+").unwrap()
        )])
    );
    let module = eval_bzl_with_loaded_children(
        RULES_CC_LINK_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/private/link:link.bzl").unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/private/link/link.bzl"),
            repository_mapping: Arc::from([]),
        },
        &children,
    )
    .unwrap();
    assert_rules_cc_link_interfaces(&module, &children);
}

#[test]
fn exact_rules_cc_linkstamp_compile_freezes_complete_producer() {
    assert_eq!(RULES_CC_LINKSTAMP_COMPILE_SOURCE.lines().count(), 111);
    assert_eq!(
        format!(
            "{:x}",
            Sha256::digest(RULES_CC_LINKSTAMP_COMPILE_SOURCE.as_bytes())
        ),
        "6f5ceb39f1b6c26b65073867f3435ec01093775edf6129d2b9421bca4c7a70bb"
    );
    let all = complete_rules_cc_compile_children();
    let children =
        [1, 2, 3, 4, 5, 9].map(|index| (all[index].0, all[index].1.clone(), all[index].2.dupe()));
    let labels = [
        "@@rules_cc+//cc:action_names.bzl",
        "@@rules_cc+//cc/common:cc_helper_internal.bzl",
        "@@rules_cc+//cc/common:semantics.bzl",
        "@@rules_cc+//cc/private:cc_info.bzl",
        "@@rules_cc+//cc/private:cc_internal.bzl",
        "@@rules_cc+//cc/private/compile:compile_build_variables.bzl",
    ];
    for (child, label) in children.iter().zip(labels) {
        assert_eq!(child.1.label, CanonicalLabel::parse(label).unwrap());
    }
    assert!(children[0].1.repository_mapping.is_empty());
    assert_eq!(
        children[1].1.repository_mapping,
        Arc::from([(
            ApparentRepoName::new("bazel_skylib").unwrap(),
            CanonicalRepoName::new("bazel_skylib+").unwrap()
        )])
    );
    assert_eq!(
        children[2].1.repository_mapping,
        Arc::from([(
            ApparentRepoName::new("platforms").unwrap(),
            CanonicalRepoName::new("platforms+").unwrap()
        )])
    );
    assert_eq!(
        children[3].1.repository_mapping,
        Arc::from([(
            ApparentRepoName::new("bazel_skylib").unwrap(),
            CanonicalRepoName::new("bazel_skylib+").unwrap()
        )])
    );
    for child in [&children[4], &children[5]] {
        assert!(child.1.repository_mapping.is_empty());
    }
    let module = eval_bzl_with_loaded_children(
        RULES_CC_LINKSTAMP_COMPILE_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/private/compile:linkstamp_compile.bzl")
                .unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/private/compile/linkstamp_compile.bzl"),
            repository_mapping: Arc::from([]),
        },
        &children,
    )
    .unwrap();
    let public = |name| module.get(name).unwrap();
    let private = |name| module.get_any_visibility(name).unwrap().0;
    for (name, child, export) in [
        (
            "LINKSTAMP_COMPILE_ACTION_NAME",
            0,
            "LINKSTAMP_COMPILE_ACTION_NAME",
        ),
        ("should_stamp", 1, "should_stamp"),
        ("cc_semantics", 2, "semantics"),
        ("EMPTY_COMPILATION_CONTEXT", 3, "EMPTY_COMPILATION_CONTEXT"),
        ("_cc_internal", 4, "cc_internal"),
        (
            "get_linkstamp_compile_variables",
            5,
            "get_linkstamp_compile_variables",
        ),
    ] {
        let value = if name.starts_with('_') {
            private(name)
        } else {
            public(name)
        };
        assert!(
            value
                .value()
                .ptr_eq(children[child].2.get(export).unwrap().value()),
            "{name}"
        );
    }
    assert_eq!(
        public("register_linkstamp_compile_action")
            .value()
            .get_type(),
        "function"
    );
    let mut names = module.names().map(|n| n.as_str()).collect::<Vec<_>>();
    names.sort_unstable();
    let mut expected="LINKSTAMP_COMPILE_ACTION_NAME should_stamp cc_semantics EMPTY_COMPILATION_CONTEXT get_linkstamp_compile_variables register_linkstamp_compile_action".split_whitespace().collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(names, expected);
    let mut all_names = module
        .names_any_visibility()
        .map(|n| n.as_str())
        .collect::<Vec<_>>();
    all_names.sort_unstable();
    expected.push("_cc_internal");
    expected.sort_unstable();
    assert_eq!(all_names, expected);
}

fn compile_owner(label: &str, path: &str, mapping: &[(&str, &str)]) -> BzlModuleIdentity {
    BzlModuleIdentity {
        label: CanonicalLabel::parse(label).unwrap(),
        workspace_path: PathBuf::from(path),
        repository_mapping: mapping
            .iter()
            .map(|(apparent, canonical)| {
                (
                    ApparentRepoName::new(*apparent).unwrap(),
                    CanonicalRepoName::new(*canonical).unwrap(),
                )
            })
            .collect::<Vec<_>>()
            .into(),
    }
}

fn compile_child(
    source: &str,
    label: &str,
    path: &str,
    mapping: &[(&str, &str)],
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) -> (BzlModuleIdentity, FrozenModule) {
    let owner = compile_owner(label, path, mapping);
    let module = eval_bzl_with_loaded_children(source, owner.clone(), children).unwrap();
    (owner, module)
}

