fn assert_compile_eager_values(compile: &FrozenModule) {
    let private = |name| compile.get_any_visibility(name).unwrap().0;
    let scratch = Module::new();
    for (name, expected) in [
        ("_VALID_CPP_SOURCE_TYPES", "SOURCE HEADER CLIF_INPUT_PROTO"),
        (
            "SOURCE_CATEGORY_CC",
            ".cc .cpp .cxx .c++ .C .cu .cl .h .hh .hpp .ipp .hxx .h++ .inc .inl .tlh .tli .H .tcc .c .s .asm .S .ipb",
        ),
        (
            "SOURCE_CATEGORY_CC_AND_OBJC",
            ".cc .cpp .cxx .c++ .C .cu .cl .h .hh .hpp .ipp .hxx .h++ .inc .inl .tlh .tli .H .tcc .m .mm .c .s .asm .S",
        ),
        ("LTO_SOURCE_EXTENSIONS", ".cc .cpp .cxx .c++ .C .cu .cl .c"),
    ] {
        let binding = if name.starts_with('_') {
            private(name)
        } else {
            compile.get(name).unwrap()
        };
        assert_eq!(binding.value().get_type(), "set", "{name}");
        let actual = binding
            .value()
            .to_value()
            .iterate(scratch.heap())
            .unwrap()
            .map(|value| value.unpack_str().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            actual,
            expected.split_whitespace().collect::<Vec<_>>(),
            "{name}"
        );
    }
    let provider = private("_CppSourceInfo");
    assert_eq!(provider.value().get_type(), "provider_callable");
    assert_eq!(
        provider.value().to_string(),
        "provider[@@rules_cc+//cc/private/compile:compile.bzl%_CppSourceInfo]"
    );
    assert_eq!(
        private("__new_cpp_source_info").value().get_type(),
        "function"
    );
    for name in [
        "_VALID_CPP_SOURCE_TYPES",
        "_CppSourceInfo",
        "__new_cpp_source_info",
    ] {
        assert!(compile.get(name).is_err(), "{name}");
    }
}

