#[test]
fn exact_rules_cc_toolchain_info_freezes_complete_dependency_free_producer() {
    assert_eq!(RULES_CC_TOOLCHAIN_INFO_SOURCE.lines().count(), 255);
    assert_eq!(
        format!(
            "{:x}",
            Sha256::digest(RULES_CC_TOOLCHAIN_INFO_SOURCE.as_bytes())
        ),
        "f19589572147b7dc8f1b16ab96791b7651923c36821aed70868a74bbfce963f5"
    );
    let owner = BzlModuleIdentity {
        label: CanonicalLabel::parse("@@rules_cc+//cc/private/rules_impl:cc_toolchain_info.bzl")
            .unwrap(),
        workspace_path: PathBuf::from("/rules_cc/cc/private/rules_impl/cc_toolchain_info.bzl"),
        repository_mapping: Arc::from([]),
    };
    let loaded_package = owner.label.package().clone();
    let (module, visibility) = eval_bzl_with_identity_and_globals_and_visibility(
        RULES_CC_TOOLCHAIN_INFO_SOURCE,
        owner,
        &loading_globals(),
    )
    .unwrap();
    let package = |value: &str| PackageIdentifier::parse_bazel_package_identifier(value).unwrap();
    for importer in [
        "@@rules_cc+//cc",
        "@@rules_cc+//cc/private",
        "@@rules_cc+//cc/private/rules_impl",
    ] {
        assert!(
            visibility.allows_load_from(&loaded_package, &package(importer)),
            "{importer}"
        );
    }
    for importer in [
        "@@rules_cc+//",
        "@@rules_cc+//cpp",
        "@@rules_cc+//other",
        "@@other+//cc",
    ] {
        assert!(
            !visibility.allows_load_from(&loaded_package, &package(importer)),
            "{importer}"
        );
    }

    let provider = module.get("CcToolchainInfo").unwrap();
    assert_eq!(provider.value().get_type(), "provider_callable");
    assert_eq!(
        provider.value().to_string(),
        "provider[@@rules_cc+//cc/private/rules_impl:cc_toolchain_info.bzl%CcToolchainInfo]"
    );
    let private_functions = [
        "_",
        "_create_cc_toolchain_info",
        "_dynamic_runtime_lib",
        "_needs_pic_for_dynamic_libraries",
        "_static_runtime_lib",
    ];
    for name in private_functions {
        assert_eq!(
            module
                .get_any_visibility(name)
                .unwrap()
                .0
                .value()
                .get_type(),
            "function",
            "{name}"
        );
        assert!(module.get(name).is_err(), "{name}");
    }
    assert_eq!(
        module.names().map(|name| name.as_str()).collect::<Vec<_>>(),
        ["CcToolchainInfo"]
    );
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    let mut expected = ["CcToolchainInfo"]
        .into_iter()
        .chain(private_functions)
        .collect::<Vec<_>>();
    expected.sort_unstable();
    assert_eq!(all, expected);
}

