fn assert_rules_cc_private_cc_common_eager_values(module: &FrozenModule) {
    let private = |name| module.get_any_visibility(name).unwrap().0;
    let provider = private("_UnboundValueProviderDoNotUse");
    assert_eq!(provider.value().get_type(), "provider_callable");
    let provider = FrozenUserProviderCallable::from_value(provider.value()).unwrap();
    assert_eq!(
        (provider.id().source_label(), provider.id().exported_name()),
        (
            "@@rules_cc+//cc/private:cc_common.bzl",
            "_UnboundValueProviderDoNotUse"
        )
    );
    let unbound = private("_UNBOUND");
    assert_eq!(unbound.value().get_type(), "provider");
    assert_eq!(
        loading_provider_id(unbound.value()).unwrap(),
        provider.id().clone()
    );
    let allowlist =
        FrozenListRef::from_value(private("_OLD_STARLARK_API_ALLOWLISTED_PACKAGES").value())
            .unwrap();
    let allowlist = allowlist
        .iter()
        .map(|value| {
            TupleRef::from_value(value.to_value())
                .unwrap()
                .iter()
                .map(|part| part.unpack_str().unwrap())
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    assert_eq!(
        allowlist,
        [vec!["", "tools/build_defs/cc"], vec!["_builtins", ""]]
    );
    let escapes_binding = private("_PATH_ESCAPE_REPLACEMENTS");
    let escapes = DictRef::from_value(escapes_binding.value())
        .unwrap()
        .iter()
        .map(|(key, value)| (key.unpack_str().unwrap(), value.unpack_str().unwrap()))
        .collect::<Vec<_>>();
    assert_eq!(
        escapes,
        [
            ("_", "_U"),
            ("/", "_S"),
            ("\\", "_B"),
            (":", "_C"),
            ("@", "_A")
        ]
    );
    assert_eq!(
        RULES_CC_PRIVATE_CC_COMMON_FUNCTIONS
            .split_whitespace()
            .count(),
        38
    );
    for name in RULES_CC_PRIVATE_CC_COMMON_FUNCTIONS.split_whitespace() {
        assert_eq!(private(name).value().get_type(), "function", "{name}");
        assert!(module.get(name).is_err(), "{name}");
    }
}

fn assert_rules_cc_private_cc_common_facade(
    module: &FrozenModule,
    children: &[(&'static str, BzlModuleIdentity, FrozenModule)],
) {
    let facade_binding = module.get("cc_common").unwrap();
    let facade = StructRef::from_value(facade_binding.value()).unwrap();
    let native_binding = children[19].2.get("native_cc_common").unwrap();
    let scratch = Module::new();
    let native_sentinel = native_binding
        .value()
        .to_value()
        .get_attr("do_not_use_tools_cpp_compiler_present", scratch.heap())
        .unwrap()
        .unwrap();
    let rows = RULES_CC_PRIVATE_CC_COMMON_FACADE_ROWS
        .split_whitespace()
        .collect::<Vec<_>>();
    assert_eq!(rows.len(), 56);
    assert_eq!(facade.iter().count(), rows.len());
    for ((actual_name, actual), row) in facade.iter().zip(rows) {
        let (expected_name, binding) = row.split_once('|').unwrap();
        assert_eq!(actual_name.as_str(), expected_name);
        if binding == "@native" {
            assert!(
                actual.to_value().ptr_eq(native_sentinel),
                "{expected_name}/{binding}"
            );
        } else {
            let expected = module.get_any_visibility(binding).unwrap().0;
            assert!(actual.ptr_eq(expected.value()), "{expected_name}/{binding}");
        }
    }
    assert!(native_sentinel.is_none());
}

fn assert_rules_cc_private_cc_common_inventory(module: &FrozenModule) {
    let mut public = module.names().map(|name| name.as_str()).collect::<Vec<_>>();
    public.sort_unstable();
    let mut expected = "CcNativeLibraryInfo create_compilation_context create_debug_context create_linking_context create_module_map merge_cc_infos merge_compilation_contexts merge_debug_context merge_linking_contexts CcLauncherInfo CcSharedLibraryHintInfo EMPTY_COMPILATION_OUTPUTS create_compilation_outputs merge_compilation_outputs compile create_compile_variables register_linkstamp_compile_action create_lto_compilation_context build_libraries create_extra_link_time_library create_library_to_link create_linker_input create_linking_context_from_compilation_outputs create_linkstamp link create_link_variables create_lto_backend_artifacts setup_common_lto_variables CcToolchainInfo create_cc_toolchain_config_info configure_features cc_common".split_whitespace().collect::<Vec<_>>();
    assert_eq!(expected.len(), 32);
    expected.sort_unstable();
    assert_eq!(public, expected);
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    expected.extend(
        "_CREATE_COMPILE_ACTION_API_ALLOWLISTED_PACKAGES _PRIVATE_STARLARKIFICATION_ALLOWLIST _cc_internal _cc_common_internal _UnboundValueProviderDoNotUse _UNBOUND _OLD_STARLARK_API_ALLOWLISTED_PACKAGES _PATH_ESCAPE_REPLACEMENTS"
            .split_whitespace(),
    );
    expected.extend(RULES_CC_PRIVATE_CC_COMMON_FUNCTIONS.split_whitespace());
    assert_eq!(expected.len(), 78);
    expected.sort_unstable();
    assert_eq!(all, expected);
}

#[test]
fn exact_rules_cc_private_cc_common_freezes_complete_recursive_producer() {
    assert_eq!(RULES_CC_PRIVATE_CC_COMMON_SOURCE.lines().count(), 788);
    assert_eq!(
        format!(
            "{:x}",
            Sha256::digest(RULES_CC_PRIVATE_CC_COMMON_SOURCE.as_bytes())
        ),
        "5e6ab737945b487759c9f039c77a066dc65bbe15cf590b566fe86029cc610762"
    );
    let children = complete_rules_cc_private_cc_common_children();
    assert_eq!(children.len(), 22);
    let labels = "cc/common:cc_helper_internal.bzl cc/private:cc_info.bzl cc/private:cc_internal.bzl cc/private:cc_launcher_info.bzl cc/private:cc_shared_library_hint_info.bzl cc/private/compile:cc_compilation_outputs.bzl cc/private/compile:compile.bzl cc/private/compile:compile_build_variables.bzl cc/private/compile:linkstamp_compile.bzl cc/private/compile:lto_compilation_context.bzl cc/private/link:create_extra_link_time_library.bzl cc/private/link:create_library_to_link.bzl cc/private/link:create_linker_input.bzl cc/private/link:create_linking_context_from_compilation_outputs.bzl cc/private/link:create_linkstamp.bzl cc/private/link:link.bzl cc/private/link:link_build_variables.bzl cc/private/link:lto_backends.bzl cc/private/rules_impl:cc_toolchain_info.bzl cc/private/rules_impl:native_cc_common.bzl cc/private/toolchain_config:cc_toolchain_config_info.bzl cc/private/toolchain_config:configure_features.bzl";
    for (child, suffix) in children.iter().zip(labels.split_whitespace()) {
        assert_eq!(
            child.1.label,
            CanonicalLabel::parse(&format!("@@rules_cc+//{suffix}")).unwrap()
        );
        assert_eq!(
            child.1.workspace_path,
            PathBuf::from(format!("/rules_cc/{}", suffix.replace(':', "/")))
        );
    }
    for (index, child) in children.iter().enumerate() {
        if [0, 1, 6, 11, 17, 20].contains(&index) {
            assert_eq!(
                child.1.repository_mapping,
                Arc::from([(
                    ApparentRepoName::new("bazel_skylib").unwrap(),
                    CanonicalRepoName::new("bazel_skylib+").unwrap(),
                )])
            );
        } else {
            assert!(child.1.repository_mapping.is_empty(), "{index}");
        }
    }
    let module = eval_bzl_with_loaded_children(
        RULES_CC_PRIVATE_CC_COMMON_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/private:cc_common.bzl").unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/private/cc_common.bzl"),
            repository_mapping: Arc::from([]),
        },
        &children,
    )
    .unwrap();
    assert_rules_cc_private_cc_common_imports(&module, &children);
    assert_rules_cc_private_cc_common_eager_values(&module);
    assert_rules_cc_private_cc_common_facade(&module, &children);
    assert_rules_cc_private_cc_common_inventory(&module);
}

