fn assert_rules_rust_utils_eager_values(module: &FrozenModule) {
    let features =
        FrozenListRef::from_value(module.get("UNSUPPORTED_FEATURES").unwrap().value()).unwrap();
    assert_eq!(
        features
            .iter()
            .map(|value| value.to_value().unpack_str().unwrap())
            .collect::<Vec<_>>(),
        [
            "thin_lto",
            "module_maps",
            "use_header_modules",
            "fdo_instrument",
            "fdo_optimize",
            "rules_rust_unsupported_feature",
        ]
    );
    let force = module
        .get_any_visibility("_FORCE_DISABLE_CC_TOOLCHAIN")
        .unwrap()
        .0;
    assert_eq!(force.value().unpack_bool(), Some(false));
    assert!(module.get("_FORCE_DISABLE_CC_TOOLCHAIN").is_err());
    let encodings = module.get_any_visibility("_encodings").unwrap().0;
    assert_eq!(TupleRef::from_value(encodings.value()).unwrap().len(), 31);
    assert!(module.get("_encodings").is_err());
    let substitutions = module.get_any_visibility("_substitutions").unwrap().0;
    assert_eq!(
        FrozenListRef::from_value(substitutions.value())
            .unwrap()
            .len(),
        63
    );
    assert!(
        module
            .get("substitutions_for_testing")
            .unwrap()
            .value()
            .ptr_eq(substitutions.value())
    );
    let encode = module.get_any_visibility("_encode_raw_string").unwrap().0;
    assert!(
        module
            .get("encode_raw_string_for_testing")
            .unwrap()
            .value()
            .ptr_eq(encode.value())
    );
}

fn assert_rules_rust_utils_functions_and_inventory(module: &FrozenModule) {
    for name in RULES_RUST_UTILS_PUBLIC_FUNCTIONS.split_whitespace() {
        assert_eq!(
            module.get(name).unwrap().value().get_type(),
            "function",
            "{name}"
        );
    }
    for name in RULES_RUST_UTILS_PRIVATE_FUNCTIONS.split_whitespace() {
        assert_eq!(
            module
                .get_any_visibility(name)
                .unwrap()
                .0
                .value()
                .get_type(),
            "function",
            "{name}"
        );
        assert!(module.get(name).is_err(), "{name}");
    }
    let mut expected = RULES_RUST_UTILS_IMPORTS
        .split_whitespace()
        .chain(RULES_RUST_UTILS_PUBLIC_FUNCTIONS.split_whitespace())
        .chain([
            "UNSUPPORTED_FEATURES",
            "substitutions_for_testing",
            "encode_raw_string_for_testing",
        ])
        .collect::<Vec<_>>();
    assert_eq!(expected.len(), 46);
    expected.sort_unstable();
    let mut public = module.names().map(|name| name.as_str()).collect::<Vec<_>>();
    public.sort_unstable();
    assert_eq!(public, expected);
    expected.extend(RULES_RUST_UTILS_PRIVATE_FUNCTIONS.split_whitespace());
    expected.extend([
        "_FORCE_DISABLE_CC_TOOLCHAIN",
        "_encodings",
        "_substitutions",
    ]);
    assert_eq!(expected.len(), 56);
    expected.sort_unstable();
    let mut all = module
        .names_any_visibility()
        .map(|name| name.as_str())
        .collect::<Vec<_>>();
    all.sort_unstable();
    assert_eq!(all, expected);
}

#[test]
fn exact_rules_rust_utils_freezes_complete_recursive_producer() {
    assert_eq!(RULES_RUST_UTILS_SOURCE.lines().count(), 1032);
    assert_eq!(
        format!("{:x}", Sha256::digest(RULES_RUST_UTILS_SOURCE.as_bytes())),
        "8aa49b9312d4ae5c4aed033aba65392a039a681b3ee21ca83da0f05acac28ace"
    );
    let children = complete_rules_rust_utils_children();
    assert_eq!(children.len(), 5);
    for (child, label, path) in [
        (
            0,
            "@@bazel_skylib+//lib:paths.bzl",
            "/bazel_skylib/lib/paths.bzl",
        ),
        (
            1,
            "@@rules_cc+//cc:find_cc_toolchain.bzl",
            "/rules_cc/cc/find_cc_toolchain.bzl",
        ),
        (
            2,
            "@@rules_cc+//cc/common:cc_common.bzl",
            "/rules_cc/cc/common/cc_common.bzl",
        ),
        (
            3,
            "@@rules_cc+//cc/common:cc_info.bzl",
            "/rules_cc/cc/common/cc_info.bzl",
        ),
        (
            4,
            "@@rules_rust+//rust/private:providers.bzl",
            "/rules_rust/rust/private/providers.bzl",
        ),
    ] {
        assert_eq!(
            children[child].1.label,
            CanonicalLabel::parse(label).unwrap()
        );
        assert_eq!(children[child].1.workspace_path, PathBuf::from(path));
    }
    assert!(children[0].1.repository_mapping.is_empty());
    assert_eq!(
        children[1].1.repository_mapping,
        Arc::from([
            (
                ApparentRepoName::new("bazel_tools").unwrap(),
                CanonicalRepoName::new("bazel_tools+").unwrap(),
            ),
            (
                ApparentRepoName::new("rules_cc").unwrap(),
                CanonicalRepoName::new("rules_cc+").unwrap(),
            ),
        ])
    );
    for child in [2, 3] {
        assert_eq!(
            children[child].1.repository_mapping,
            Arc::from([(
                ApparentRepoName::new("cc_compatibility_proxy").unwrap(),
                CanonicalRepoName::new("rules_cc++compatibility_proxy+cc_compatibility_proxy")
                    .unwrap(),
            )])
        );
    }
    assert!(children[4].1.repository_mapping.is_empty());
    let module = eval_bzl_with_loaded_children(
        RULES_RUST_UTILS_SOURCE,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_rust+//rust/private:utils.bzl").unwrap(),
            workspace_path: PathBuf::from("/rules_rust/rust/private/utils.bzl"),
            repository_mapping: Arc::from([
                (
                    ApparentRepoName::new("bazel_skylib").unwrap(),
                    CanonicalRepoName::new("bazel_skylib+").unwrap(),
                ),
                (
                    ApparentRepoName::new("rules_cc").unwrap(),
                    CanonicalRepoName::new("rules_cc+").unwrap(),
                ),
            ]),
        },
        &children,
    )
    .unwrap();
    assert_rules_rust_utils_imports(&module, &children);
    assert_rules_rust_utils_eager_values(&module);
    assert_rules_rust_utils_functions_and_inventory(&module);
}

