fn eval_global(source: &str, globals: &Globals) -> Result<FrozenModule, String> {
    let ast = AstModule::parse("BUILD.bazel", source.to_owned(), &Dialect::Bazel).unwrap();
    let module = Module::new();
    let context = BzlEvaluationContext::new("//:defs.bzl");
    let mut evaluator = Evaluator::new(&module);
    evaluator.extra = Some(&context);
    evaluator
        .eval_module(ast, globals)
        .map_err(|error| error.to_string())?;
    drop(evaluator);
    module.freeze().map_err(|error| format!("{error:?}"))
}

#[test]
fn bazel_configuration_field_is_bzl_only_and_fails_closed() {
    let bzl = loading_globals();
    let binding = eval_global("FIELD = configuration_field", &bzl).unwrap();
    assert_eq!(binding.get("FIELD").unwrap().value().get_type(), "function");
    assert!(eval_global("FIELD = configuration_field", &build_file_loading_globals()).is_err());
    for source in [
        "X = configuration_field()",
        "X = configuration_field('f')",
        "X = configuration_field(name = 'n')",
        "X = configuration_field('f', 'n', 'extra')",
        "X = configuration_field(1, 'n')",
        "X = configuration_field('f', 1)",
    ] {
        assert!(eval_global(source, &bzl).is_err(), "{source}");
    }
    assert!(
        AstModule::parse(
            "BUILD.bazel",
            "X = configuration_field(fragment = 'f', fragment = 'again', name = 'n')".to_owned(),
            &Dialect::Bazel
        )
        .is_err()
    );
    let error = |source| eval_global(source, &bzl).unwrap_err();
    let diagnostic = |source| {
        error(source)
            .lines()
            .find(|line| line.starts_with("error: "))
            .unwrap()
            .to_owned()
    };
    for source in [
        "X = configuration_field('f', 'n')",
        "X = configuration_field('f', name = 'n')",
        "X = configuration_field(fragment = 'f', name = 'n')",
        "X = configuration_field(name = 'n', fragment = 'f')",
    ] {
        assert_eq!(
            diagnostic(source),
            "error: configuration_field is unsupported in Slug loading"
        );
    }
    let owner = BzlModuleIdentity {
        label: CanonicalLabel::parse("@@rules_cc+//cc/common:semantics.bzl").unwrap(),
        workspace_path: PathBuf::from("/rules_cc/cc/common/semantics.bzl"),
        repository_mapping: Arc::from([]),
    };
    let frozen = eval_bzl_with_identity(
        "def deferred(): return configuration_field(fragment = 'f', name = 'n')\n",
        owner,
    )
    .unwrap();
    assert_eq!(
        frozen.get("deferred").unwrap().value().get_type(),
        "function"
    );
}

#[test]
fn bazel_zero_argument_depset_freezes_empty_in_bzl_and_build_globals() {
    let source = "events = []\ndef eager(a = depset(), b = depset(), c = depset(), d = depset(), e = depset()):\n    events.append(\"body\")\nEMPTY = depset()\nONE = depset([\"first\", \"second\"])\n";
    let bzl = eval_bzl_with_identity(
        source,
        BzlModuleIdentity {
            label: CanonicalLabel::parse("@@rules_cc+//cc/private:objc_info.bzl").unwrap(),
            workspace_path: PathBuf::from("/rules_cc/cc/private/objc_info.bzl"),
            repository_mapping: Arc::from([]),
        },
    )
    .unwrap();
    let build = eval_global("EMPTY = depset()", &build_file_loading_globals()).unwrap();
    for module in [&bzl, &build] {
        let empty = module.get("EMPTY").unwrap();
        assert_eq!(empty.value().get_type(), "depset");
        assert!(
            StarlarkDepset::direct_from_value(empty.value())
                .unwrap()
                .is_empty()
        );
    }
    let one_binding = bzl.get("ONE").unwrap();
    let one = StarlarkDepset::direct_from_value(one_binding.value()).unwrap();
    assert_eq!(one[0].unpack_str(), Some("first"));
    assert_eq!(one[1].unpack_str(), Some("second"));
    assert_eq!(
        FrozenListRef::from_value(bzl.get("events").unwrap().value())
            .unwrap()
            .len(),
        0
    );
    let globals = loading_globals();
    for rejected in [
        "X = depset(direct = [])",
        "X = depset(transitive = [])",
        "X = depset(order = \"default\")",
        "X = depset(unknown = [])",
        "X = depset(\"bad\")",
        "X = depset([], [])",
    ] {
        assert!(eval_global(rejected, &globals).is_err(), "{rejected}");
    }
}

#[test]
fn bazel_set_is_shared_by_bzl_and_build_without_overlay_leaks() {
    let bzl_globals = loading_globals();
    let build_globals = build_file_loading_globals();
    assert!(bzl_globals.names().any(|name| name.as_str() == "struct"));
    assert!(!build_globals.names().any(|name| name.as_str() == "struct"));
    for globals in [&bzl_globals, &build_globals] {
        let names = globals
            .names()
            .map(|name| name.as_str())
            .collect::<Vec<_>>();
        assert!(names.contains(&"set"));
        assert!(!names.contains(&"chr"));
        assert!(!names.contains(&"ord"));
        let frozen = eval_global(
            "ORIGINAL=set([3,1,3,2])\nCOPY=set(ORIGINAL)\nCOPY.add(4)\nCOPY.add(1)\nORIGINAL_VALUES=list(ORIGINAL)\nCOPY_VALUES=list(COPY)\nEMPTY_VALUES=list(set())\nHAS_ONE=1 in COPY\nKIND=type(COPY)\ndef deferred(value):\n    paths=set()\n    if value not in paths:\n        paths.add(value)\n    return paths\n",
            globals,
        )
        .unwrap();
        let ints = |name| {
            FrozenListRef::from_value(frozen.get(name).unwrap().value())
                .unwrap()
                .iter()
                .map(|value| value.unpack_i32().unwrap())
                .collect::<Vec<_>>()
        };
        assert_eq!(ints("ORIGINAL_VALUES"), [3, 1, 2]);
        assert_eq!(ints("COPY_VALUES"), [3, 1, 2, 4]);
        assert!(ints("EMPTY_VALUES").is_empty());
        assert_eq!(
            frozen.get("HAS_ONE").unwrap().value().unpack_bool(),
            Some(true)
        );
        assert_eq!(
            frozen.get("KIND").unwrap().value().unpack_str(),
            Some("set")
        );
        assert_eq!(frozen.get("ORIGINAL").unwrap().value().get_type(), "set");
        assert_eq!(frozen.get("COPY").unwrap().value().get_type(), "set");
        assert!(
            SetMut::from_value(frozen.get("COPY").unwrap().value().to_value()).is_err(),
            "an exported frozen set must reject mutation"
        );
        assert_eq!(
            frozen.get("deferred").unwrap().value().get_type(),
            "function"
        );
        for rejected in [
            "X=set(elements=[])",
            "X=set([], [])",
            "X=set(1)",
            "X=set([[1]])",
        ] {
            assert!(eval_global(rejected, globals).is_err(), "{rejected}");
        }
    }
}

#[test]
fn bazel_config_typed_descriptors_are_bzl_only_and_require_supported_flags() {
    let bzl = loading_globals();
    eval_global(
        "IT=config.int(flag=True)\nIO=config.int()\nIF=config.int(flag=False)\nBT=config.bool(flag=True)\nBO=config.bool()\nBF=config.bool(flag=False)",
        &bzl,
    )
    .unwrap();
    for source in [
        "X=config.int(True)",
        "X=config.int(flag=None)",
        "X=config.int(flag=1)",
        "X=config.int(unknown=True)",
    ] {
        assert!(eval_global(source, &bzl).is_err(), "{source}");
    }
    for source in [
        "X=config.bool(True)",
        "X=config.bool(flag=None)",
        "X=config.bool(flag=1)",
        "X=config.bool(unknown=True)",
    ] {
        assert!(eval_global(source, &bzl).is_err(), "{source}");
    }
    eval_global(
        "ST=config.string(flag=True)\nSO=config.string()\nSF=config.string(flag=False, allow_multiple=False)\nSM=config.string(flag=True, allow_multiple=True)\nOM=config.string(allow_multiple=True)",
        &bzl,
    )
    .unwrap();
    for source in [
        "X=config.string(True)",
        "X=config.string(flag=None)",
        "X=config.string(flag=1)",
        "X=config.string(allow_multiple=None)",
        "X=config.string(allow_multiple=1)",
        "X=config.string(unknown=True)",
    ] {
        assert!(eval_global(source, &bzl).is_err(), "{source}");
    }
    for source in [
        "X=config.string_list(True)",
        "X=config.string_list(flag=None)",
        "X=config.string_list(flag=1)",
        "X=config.string_list(repeatable=None)",
        "X=config.string_list(repeatable=1)",
        "X=config.string_list(unknown=True)",
    ] {
        assert!(eval_global(source, &bzl).is_err(), "{source}");
    }
    eval_global(
        "L=config.string_list(flag=True)\nE=config.string_list(flag=True, repeatable=False)\nR=config.string_list(flag=True, repeatable=True)\nO=config.string_list()\nF=config.string_list(flag=False)\nFF=config.string_list(flag=False, repeatable=False)",
        &bzl,
    )
    .unwrap();
    for source in [
        "X=config.string_list(repeatable=True)",
        "X=config.string_list(flag=False, repeatable=True)",
    ] {
        let error = eval_global(source, &bzl).unwrap_err();
        assert!(
            error.contains("'repeatable' can only be set for a setting with 'flag = True'"),
            "{error}"
        );
    }
    let build = build_file_loading_globals();
    eval_global("S=config.string(flag=True)", &build).unwrap();
    for source in [
        "S=config.string()",
        "S=config.string(flag=True, allow_multiple=True)",
        "S=config.string(flag=True, unknown=True)",
    ] {
        assert!(eval_global(source, &build).is_err(), "{source}");
    }
    for (source, missing) in [
        ("S=config.string(flag=True)\nI=config.int()", "int"),
        (
            "S=config.string(flag=True)\nB=config.bool(flag=True)",
            "bool",
        ),
        (
            "S=config.string(flag=True)\nL=config.string_list(flag=True)",
            "string_list",
        ),
    ] {
        let error = eval_global(source, &build).unwrap_err();
        assert!(error.contains(missing), "{error}");
    }
}

